import{_ as r,C as i,o as s,c,a2 as n,j as t,a,E as o}from"./chunks/framework.Di-jvWLj.js";const v=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1793027063000}'),h={name:"roadmap.md"},l={id:"m1-issue-triage-end-to-end",tabindex:"-1"},p={id:"m2-mail-digest",tabindex:"-1"},m={id:"m3-dependency-upgrade",tabindex:"-1"};function u(g,e,b,k,w,f){const d=i("Badge");return s(),c("div",null,[e[9]||(e[9]=n('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>chamvi is built milestone by milestone, each defined by one real agent that has to work end to end. Everything on this page except the shipped packages is <strong>planned</strong>: designed, not built. There are no dates.</p><h2 id="shipped" tabindex="-1">Shipped <a class="header-anchor" href="#shipped" aria-label="Permalink to &quot;Shipped&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Contents</th></tr></thead><tbody><tr><td><code>@chamvi/core</code></td><td><code>defineAgent()</code> with channel subscriptions and tool hooks, the <code>IChannel</code> contract (<code>ToolContext.channels</code>, <code>consoleChannel()</code>), <code>Engine</code> (dispatch, scheduling, checkpoints, budgets, durable <code>approve()</code>, cancel, drain, recovery), effect tools, agent state, the <code>IStore</code> contract, <code>MemoryStore</code></td></tr><tr><td><code>@chamvi/test-kit</code></td><td><code>describeStoreContract</code>, <code>describeWorkspaceContract</code>, <code>ControllableClock</code>, <code>createGitFixture</code>, <code>createFakeGithub</code></td></tr><tr><td><code>@chamvi/channel-cron</code></td><td>The cron channel <code>cronChannel()</code> and <code>cron.on()</code> (one locked hubwire component per subscription, overlap policies, timezones), <code>runJob()</code> for one-shot jobs</td></tr><tr><td><code>@chamvi/store-typeorm</code></td><td><code>TypeormStore</code> on Postgres, <code>migrateStore</code>, <code>purgeExpired</code>. See <a href="/stores/typeorm">TypeORM store</a></td></tr><tr><td><code>@chamvi/http</code></td><td>REST control API, server-sent events, the <code>http</code>, <code>mcp</code> and <code>webhook</code> channels and the <code>/channels/&lt;name&gt;</code> mount, <code>/healthz</code>, <code>/readyz</code>, <code>/metrics</code>, the MCP endpoint, static-token, authup and OIDC authentication, graceful shutdown. See <a href="/guide/http">HTTP API &amp; MCP</a></td></tr><tr><td><code>@chamvi/github</code></td><td>GitHub App auth with an installation-token cache, the GitHub channel (signed deliveries in, deduplicated by delivery id; issue comments out, deduplicated by a hidden marker), <code>github.on()</code> subscriptions, read tools and effect write tools with marker reconciliation. See <a href="/deployment/github-app">GitHub App</a></td></tr><tr><td><code>@chamvi/sandbox</code></td><td>Sandbox contracts, path, repository and limit rules, the run-scoped workspace manager with <code>create_workspace</code> and <code>dispose_workspace</code>, workspaces a run finds again after a restart or on another replica. See <a href="/guide/workspaces">Workspaces &amp; Coding</a></td></tr><tr><td><code>@chamvi/sandbox-local</code>, <code>@chamvi/sandbox-docker</code>, <code>@chamvi/sandbox-k8s</code></td><td>Workspace providers: a temporary directory (development), a container per workspace, a pod per workspace (root inside, strict at the edge, a hardened mode, a shared package cache); the <code>ghcr.io/chamvi/sandbox-dev</code> image with mise for any toolchain</td></tr><tr><td><code>@chamvi/channel-openclaw</code></td><td>The OpenClaw channel: messages and approval requests into an OpenClaw chat through its hooks endpoint, with an <code>Idempotency-Key</code>. See <a href="/deployment/openclaw">OpenClaw</a></td></tr><tr><td><code>@chamvi/coding</code></td><td>Coding tools (<code>read_file</code>, <code>write_file</code>, <code>edit_file</code>, <code>grep</code>, <code>list_files</code>, <code>bash</code>, <code>git_diff</code>) over a run&#39;s workspaces and the <code>ICodingBackend</code> contract</td></tr><tr><td><code>@chamvi/ui</code></td><td>Vue 3 dashboard served by <code>uiRoutes()</code>: an agents overview, runs started from the agent page, runs with live steps, an approvals inbox, agent state, schedules</td></tr><tr><td><code>@chamvi/app</code>, <code>@chamvi/cli</code></td><td><code>createApp()</code> with orkos modules booted from env (store, engine, channels, HTTP, GitHub, sandbox, OpenClaw, UI, authup) and the <code>chamvi</code> bin with <code>dev</code>, <code>build</code>, <code>start</code>, <code>run-job</code> and <code>migrate</code>. See <a href="/guide/app">Apps &amp; Modules</a></td></tr></tbody></table><h2 id="milestones" tabindex="-1">Milestones <a class="header-anchor" href="#milestones" aria-label="Permalink to &quot;Milestones&quot;">​</a></h2>',5)),t("h3",l,[e[0]||(e[0]=a("M1: issue triage end to end ",-1)),o(d,{type:"warning",text:"Planned"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#m1-issue-triage-end-to-end","aria-label":'Permalink to "M1: issue triage end to end <Badge type="warning" text="Planned" />"'},"​",-1))]),e[10]||(e[10]=t("p",null,"On every new issue in the owner's repositories, a triage agent labels it, checks for duplicates, tries to reproduce the bug against the latest release in a sandbox and posts a first reply asking for missing details. A periodic sweep catches issues missed while the agent was down.",-1)),e[11]||(e[11]=t("p",null,"M1 is done only when everything it needs ships: the TypeORM store, the cron channel, the HTTP and MCP API with authentication, the GitHub channel and tools, sandboxes with coding tools, the OpenClaw channel, the UI, the CLI, the base image, the Helm chart (with the sandbox RBAC and an egress NetworkPolicy), the template repository, and the triage agent itself, deployed with Flux.",-1)),t("h3",p,[e[3]||(e[3]=a("M2: mail digest ",-1)),o(d,{type:"warning",text:"Planned"}),e[4]||(e[4]=a()),e[5]||(e[5]=t("a",{class:"header-anchor",href:"#m2-mail-digest","aria-label":'Permalink to "M2: mail digest <Badge type="warning" text="Planned" />"'},"​",-1))]),e[12]||(e[12]=t("p",null,[a("Every morning, and on request through OpenClaw, the owner gets a short digest: what matters today, what still needs action, what is waiting on others. Open loops are tracked in typed state collections across days. M2 adds a mail (IMAP) channel and "),t("strong",null,"threaded runs"),a(": a new run continues the conversation of an earlier one at the same channel address.")],-1)),t("h3",m,[e[6]||(e[6]=a("M3: dependency upgrade ",-1)),o(d,{type:"warning",text:"Planned"}),e[7]||(e[7]=a()),e[8]||(e[8]=t("a",{class:"header-anchor",href:"#m3-dependency-upgrade","aria-label":'Permalink to "M3: dependency upgrade <Badge type="warning" text="Planned" />"'},"​",-1))]),e[13]||(e[13]=n('<p>When Renovate opens a pull request, an agent reads the changelog of the bumped package, fixes breaking changes in a sandbox, runs the tests and pushes commits. It pings the owner only when it is stuck. M3 adds long coding runs, a Claude Code coding backend and stuck detection.</p><h2 id="planned-packages" tabindex="-1">Planned packages <a class="header-anchor" href="#planned-packages" aria-label="Permalink to &quot;Planned packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Status</th><th>Purpose</th></tr></thead><tbody><tr><td>Coding backend on the own tools</td><td>Planned (M1)</td><td>An <code>ICodingBackend</code> that runs the coding tools in a nested tool loop</td></tr><tr><td><code>@chamvi/coding-claude-code</code></td><td>Planned (M3)</td><td>A coding backend that runs Claude Code inside the sandbox</td></tr><tr><td>Deploy kit</td><td>Planned (M1)</td><td>A base image, a Helm chart and a template repository around <code>@chamvi/app</code> and <code>@chamvi/cli</code>. See <a href="/deployment/">Deployment</a></td></tr><tr><td><code>@chamvi/mail</code></td><td>Planned (M2)</td><td>IMAP channel and tools</td></tr><tr><td>Chat channel</td><td>Planned</td><td>A chat channel (#32) on the channel contract</td></tr></tbody></table><p>Two changes happened upstream first: a lock hook, timezone support and the scheduled time per tick shipped in <a href="https://github.com/tada5hi/hubwire" target="_blank" rel="noreferrer">hubwire</a> 0.2.2 (for the cron channel), and a fetch-native token verification in <a href="https://github.com/authup/authup" target="_blank" rel="noreferrer">authup</a> 1.0.0-beta.70 (for the HTTP API).</p><h2 id="stability" tabindex="-1">Stability <a class="header-anchor" href="#stability" aria-label="Permalink to &quot;Stability&quot;">​</a></h2><p>chamvi is pre-1.0 and owner-first. Until M3, minor versions may break the API and the store schema.</p>',6))])}const P=r(h,[["render",u]]);export{v as __pageData,P as default};
